   "content": "王姐把文件夹摔在桌上的时候，林满月的手机正在桌角震。\n\n短信预览弹出来：【林女士，您尾号7839账户本期应还……】她手快，翻面扣住。\n\n“《心动倒计时》收官集播完，数据再跌，你工位腾出来。”王姐把A4纸往她面前推，纸边刮过桌面，“签。”\n\n林满月拿起责任书。条款几行字很清楚：数据未达保底，自愿承担违约金二十万。她扫了一眼对面的周明，他正低头转笔，笔杆上贴着“爆款制造机”的卡通贴纸，还是她去年送他的。\n\n“王姐，”林满月把纸翻了一面，“原方案里甜宠线——”\n\n“改。”\n\n周明从她右手边抽走那叠原方案文件夹，翻开看了两页，啧啧有声：“满月，这版我先借走参考参考。”\n\n“那是原方案。”\n\n“王姐说改。”周明合上文件夹，夹在腋下，走到门口回头，“按你的剪法只会更死。别怪我提前提醒过你。”\n\n周明见林满月没有抬头，于是快速的拿起手机偷拍了几下屏幕后，迅速消失在门口。\n\n实习生小鹿缩在会议桌最末，手里捏着一杯凉透的美式，等门关紧才敢递过去：“姐，你脸色不太……”\n\n“没事。”林满月在责任书落笔处签了名，笔划到最后一下，手机又震。她没看。\n\n王姐把责任书收进文件夹：“从现在起，封版前别再来找我加预算。还有——资方昨天点名了，收官嘉宾想请陆淮舟来救场。”\n\n“他不是拒过一次？”\n\n“所以你再去问一次。”王姐起身，高跟鞋敲得地面哒哒响，“拿不下来，你看着办。”\n\n四壁白墙的剪辑机房比会议室冷五度。林满月坐在三块监视器前，桌上堆着带时间码的素材硬盘。小鹿把凉美式放下就溜了。\n\n她按下空格键，样片放到第三段。男二给女三递奶茶，镜头切得平平整整，连嘴角弧度都像量过的。\n\n她站起来去够架子上的糖包，低血糖从指尖开始麻。手抓空了，膝盖撞在监视器支架上，整个人往前一扑，脑门磕在屏幕边缘。\n\n眼前白了一瞬。\n\n再睁眼，监视器还亮着，画面还是那段奶茶戏。但上面浮出了一层薄薄的半透明字——\n\n【又是工业糖精，"
