   "content": "海城影视基地的闸口比节目组的棚还难进。林满月两点五十到，门禁刷了三次，红灯。\n\n“访客证。”保安抬眼皮。\n\n“约了陆老师。”\n\n“休息棚不接待外客。”\n\n她退到铁栏边。手机连着震——王姐语音：“跟陆淮舟说了没？资方上午又催。按昨天说的24小时，到今天下午四点数据不抬头，责任书就生效；三天期限不变，今天你先把人稳住，拿不下三天后才砍。”紧跟着医院系统短信：【住院费最后缴款周期，25日前逾期取消床位。】她把手机塞回口袋，手是冰的。\n\n陆助理小跑过来，跟保安招呼一声，领她绕过主棚。场务正扛轨道往7号棚送，铁扣子磕在地上，一声接一声。\n\n“陆老师还在看通告，先休息棚等，三点半收工。”陆助理递给她一瓶水，“U盘带了？”\n\n“带了。”\n\n“他今天心情一般。你道歉——别绕。”\n\n休息棚是两辆房车中间拉了块黑遮阳布。林满月坐在折叠椅上，U盘放在膝盖上。房车顶棚浮出半透明弹幕：\n\n【来蹲陆老师了。这姐谁？】\n【手里拿U盘，又来求合作吧。】\n\n昨天磕了脑门才看见这东西，现在不是追究原因的时候。\n\n三点四十，陆淮舟从棚里出来。帽子没摘，黑连帽衫袖口卷到手肘，经过折叠椅脚步没停。\n\n“陆老师。”林满月站起来。\n\n他回头看她，又看U盘。\n\n“道歉。”他说。\n\n“昨天在地库撞到您，弄脏大衣，是我赶时间没看路，对不起。”她把U盘往前一递，“改过的试片，两分五十秒。”\n\n陆淮舟接过去，走到房车边插进笔记本，坐在踏板上。林满月站着。\n\n试片弹出。奶茶戏压到后半段，开场是男二递手机，视线斜过去，停三秒以上。\n\n他没说话。林满月数到四，画面里男二眼神的细节抽了一下。陆淮舟按暂停。\n\n“这镜头谁剪的？”\n\n“我。”\n\n“原来的呢？”\n\n“被标了废镜头。”\n\n“谁标的？”\n\n“周明。上午标完扔进弃用素材了。”\n\n陆淮舟没接话，按空格。视频继续，节奏快，音效压底，背景音乐几乎没存在感。\n\n看完，拔U盘，抬头。心动值标"
