   "words": 2705,
   "content": "林满月把平板扣在膝上，拇指按下截屏。照片、配文、定位打卡，一张不落存进相册，又调出昨天机房外走廊的监控截图——周明贴门玻璃那三连拍，她上午让小鹿从安保室调的。两秒，截图并排打在备忘录里，时间戳一行行对齐。\n\n她点开王姐私信，发过去。文字打了两行：照片时间戳18:51，周明地库打卡18:51，但他18:50—18:53正在机房外连拍我屏幕，三张连拍带时间水印，要发您核对。\n\n发送。她又补一句：另外照片里咖啡渍已洇开，是撞后状态，不是撞前。地库斜坡到机房步行六分钟，他不可能同时站两个位置。\n\n陆助理在旁边看她打完，递自己手机过来：“林老师，陆老师那边让我转达——正式合同草案出来了，出镜范围写的是‘以编剧身份配合节目宣发所需的反应镜头及短采访’，时长每次不超过十分钟，素材先过节目组样再给陆方过目。保密条款单独列了。”\n\n林满月翻了翻，截图发给王姐：“这个也一并发您，我这边先过。”\n\n话音没落，手机震。工作群语音会邀请，王姐发起。林满月点了接听。\n\n“说。”王姐那边键盘声没停。\n\n“照片时间戳18:51，周明地库访客打卡18:51，但他18:50到18:53在机房外走廊连拍我屏幕三张，带时间水印。我发您私信了，两张截图并排——”\n\n“行了。”王姐打断，“监控呢？你调了没有？”\n\n“机房外走廊的调了，地库的还没——”\n\n“别调了。”王姐键盘声一停，“照片我看了，角度是斜坡柱子后面。周明，你说。”\n\n周明的声音切进来，比平时低半度：“我地库访客卡昨天下午借给外聘剪辑了，他拿去拍空镜素材。我人确实在机房，卡在他手上，打卡记录挂我名下我也没办法。照片不是我拍的。”\n\n林满月没接茬，直接问：“外聘剪辑叫什么？哪个公司的？昨天几点借的卡？借卡记录有吗？”\n\n“你审我？”周明音量提了。\n\n“我在找拍照片的人。”林满月把平板翻到备忘录那页，“你借卡给谁，谁进地库拍了我，照片又用你账号发进工作群——"
