   "num": 15,
   "title": "入职当天的访问记录",
   "words": 2143,
   "content": "林满月攥着方向盘的指节泛白，车载导航屏幕上48小时倒计时的数字正以肉眼可见的速度跳动——29小时16分47秒。她猛地打了把方向盘，轮胎蹭过路边的路肩，发出尖锐的摩擦声，车子在深夜的马路上划出一道急弯，掉头往台里的方向冲。\n\n手机屏幕还亮着，小鹿发来的端口日志截图在黑暗里泛着冷光。连续三次访问加密鱼饵节点的IP，前缀和导播台那个不明端口的前缀完全匹配。她把手机架在出风口，声音压得很低：“马上把完整的端口日志导出来，带操作特征，包括访问时间、停留时长、有没有尝试破解加密。”\n\n小鹿的声音带着气喘，背景里是台里技术部办公室的键盘声：“姐，已经在导了，这个IP的操作习惯很怪，每次访问都卡着系统日志自动备份的前一秒，像是故意要抹掉操作痕迹。”\n\n“重点看第三次访问的时间。”林满月一脚油门踩到底，引擎的轰鸣声盖过了风噪，“有没有和什么事对得上的时间点？”\n\n电话那头传来鼠标点击的声音，几秒后，小鹿的声音猛地拔高：“第三次访问时间是18点47分32秒！刚好是……”\n\n“刚好是周明在男卫生间删除‘鱼饵-勿删.mp4’的时间。”林满月接过话，心脏猛地缩了一下。那个时间点她记得太清楚了，周明砸在洗手台上的手机屏幕，“文件已删除”的提示，和端口日志里的访问记录，分秒不差。\n\n车子“吱”地一声刹在台里的地下车库，林满月拽着包冲上楼，技术部办公室的门虚掩着，小鹿正盯着屏幕，手指在键盘上快速敲击。\n\n“姐，你看。”小鹿把屏幕转过来，端口日志的表格里，三次访问记录被标成了红色，“这个IP的操作特征，和导播台隐藏节点的操作者完全一致——都是卡备份前一秒，都是用同一种加密破解指令，甚至连每次访问的间隔时间都一模一样。”\n\n林满月俯身盯着屏幕，指尖点在第三次访问的时间戳上：“还有呢？”\n\n“还有……”小鹿滑动鼠标滚轮，把日志往下拉，“这个IP在倒计时启动后，还访问过一个内部文件，是你的编剧权限确认文件，时间是"
