   "title": "碎片上的陌生签名",
   "words": 2348,
   "content": "指尖的凉意顺着打印纸边缘爬进指缝，林满月攥着纸的指节泛白，指腹蹭到纸面上的IP前缀，和王丽私人邮箱绑定的端口前缀，分毫不差。她把打印纸塞进帆布袋暗袋，拽紧拉链，抬眼看向王丽办公室紧闭的门。上午八点五十八分，48小时倒计时剩余28小时57分。\n\n技术部的小鹿跟在她身后，手里攥着另一份端口日志备份，指尖沾着打印机刚出来的墨粉：“姐，九点差两分了，要进去吗？”\n\n林满月没回头，只抬手摸了摸帆布袋里的证据本，封面硬壳硌着掌心：“走。”\n\n两人走到王丽办公室门口，小鹿刚要敲门，林满月抬手按住她的手腕，侧耳贴在门上听了两秒。办公室里没有声音，只有空调出风口的风声，闷得像没透气的罐头。\n\n林满月松开手，用指节敲了三下门，节奏稳得像她之前在导播台切信号的频率。\n\n门里传来王丽的声音，带着点刻意压出来的冷：“进来。”\n\n林满月推开门，办公室的灯开得很亮，王丽坐在办公桌后面，面前摊着台里的权责表，指尖点在“导播台端口监管”那一行。小鹿跟在她身后，刚要往里走，王丽抬眼扫过来：“你出去，我和林编剧单独谈。”\n\n小鹿的脚步顿住，看向林满月。林满月冲她点了点头，声音很轻：“去门口等着，别让任何人靠近。”\n\n小鹿咬了咬唇，转身带上门，办公室里只剩林满月和王丽两个人，空气里飘着王丽常用的玫瑰香水味，混着空调的干燥味，让人鼻子有些发酸。\n\n王丽把权责表往旁边一推，靠在椅背上，指尖敲着桌面：“端口的事，你查到什么了？”\n\n林满月走到办公桌前，把帆布袋里的证据本拿出来，放在桌上，翻开到第13页，端口日志的截图贴在上面：“连续三次访问鱼饵节点的IP，前缀和你私人邮箱绑定的端口前缀完全匹配。”\n\n王丽的指尖敲桌面的动作停了，脸上的表情没什么变化，只有眼角的肌肉抽了一下：“然后呢？”\n\n“这个IP，9月26日，也就是我入职当天，访问过台里的人力系统，下载了我的个人简历。”林满月的声音很稳，每一个字都像砸在桌面上，“还"
