   "title": "监视开始",
   "words": 3076,
   "content": "林满月将碎片在桌面上小心拼凑，边缘的撕裂声在空旷的资料室里格外清晰。她蹲下身，指尖在光可鉴人的地板上移动，把先前从王丽办公室垃圾桶里带回来的那几块碎纸片一一归位。帆布袋敞开在她身旁，露出里面深褐色的证据本，边角已被翻得起毛。\n\n“编号H07...”她低声念着，把一块边缘参差的碎片对准另一块。纸上露出的线条逐渐连成一个矩形，中间有交叉的斜线——那是风井的俯视图。她的呼吸放慢，指尖在拼好的部分上轻轻描过。这图她见过，陆淮舟手绘的那张，背面写着“那天有人比你先到”。\n\n她摸出手机，调出证据本里存的那张手绘图照片。将屏幕上的图形与手中碎片的残影并排比对。吻合。碎片上的编号序列，与陆淮舟图上的标注顺序完全一致，指向一个她从未注意过的点——检修梯第三级，旁边用铅笔圈了个小圈，标注“此处”。\n\n林满月的指尖在那个圈上停留了一秒。她记得SD卡第11帧里那个模糊的人影，高个，帽檐压后颈，就站在风井玻璃上映出的位置。时间是18:50。她记得周明打卡记录是18:51。\n\n她继续拼。另一块碎片上有个签名，笔画有力，收笔处习惯性地拖个小勾。那是综艺部总监的签名，她之前在台里文件上见过。签名旁边，是一串数字，像是某个内部编号。她把这块碎片举到灯光下，编号的尾数与她刚才拼出的风井图编号尾数相同。\n\n“总监的签名……”她 murmured。这已经不是王丽层面的问题了。她想起王丽提到的“高层交易”，想起那条被掐断的蓝V弹幕，想起第四页文件早于她入职两周的诡异时间。线索像散落的珠子，现在被这根线慢慢串了起来。\n\n她坐直身体，膝盖碰到桌沿，一阵轻微的麻。低血糖的后遗症还没完全过去。她活动了一下手指，拿起笔，在证据本的空白处画下简图，标注上编号和签名的位置。然后，她拿起手机，给陆淮舟发了条消息：“风井图碎片拼出来了。检修梯第三级。需要你确认一些细节。”\n\n发送成功，她起身，把碎片小心地装进一个透明文件袋。她拉开帆"
