   "title": "废弃机房的第七个关键点",
   "words": 2114,
   "content": "林满月踩在熄灭的声控灯阴影里。手机屏光映在脸上，惨白如纸。\n\n手指悬在拨号键上，最终按下取消。不打了。既然是猎物，就得学会咬断猎人的喉咙。\n\n她贴墙移动，鞋底摩擦地面沙沙作响。刚走五米，视网膜左上角弹出血红半透明字：【后方热源移动，距离三米，锁定中。】\n\n林满月后背绷紧。这是第一次物理威胁预警。她没回头，借应急灯反光向右滑步，甩出帆布袋。包带撞在铁柱上发出闷响。脚步声戛然而止。\n\n她屏息贴墙移动，绕过承重柱，确认无新红字后朝出口走去。直到看见地面光晕。\n\n十分钟后，黑色轿车停在梧桐树下。车窗降下一半。副驾驶坐着陆淮舟。驾驶座上是个沉默的司机，始终没回头。陆淮舟穿着黑色连帽衫，帽檐压得很低，手里把玩着银色打火机，拇指摩挲滚轮，火苗一明即灭。\n\n“上来。”声音平淡。\n\n林满月拉开后门坐进后座。车厢安静。她从帆布袋摸出风井捡到的 U 盘，指尖微凉，递到陆淮舟手边。“数据源在这里。”\n\n陆淮舟没回头，左手接过 U 盘，顺势塞进连帽衫内侧口袋，动作流畅。\n\n蓝牙连接瞬间，车载音响传出低频噪音，像心跳监测仪，五秒后消失。“这是什么？”林满月问，手指扣紧安全带。指尖因低血糖微麻。\n\n“系统干扰。”陆淮舟低头点烟，火光映亮下颌，“你的能力被反向追踪，屏蔽器只能挡一部分。”烟雾里，他吐出的烟圈维持了短暂数字形状——7。\n\n林满月盯着烟圈：“推进陷阱，也是计划的一环？”\n\n陆淮舟没否认。他按灭烟，左手搭膝。无名指关节有新鲜划痕，位置与风井检修图编号 F070 吻合。\n\n“不把你当活饵，总监不会露底。”陆淮舟转头，眼神冷硬藏疲惫，“王丽是棋子，操盘手需更高权限。你的‘编剧’身份，比我的流量有价值。”\n\n“那我呢？棋子还是人质？”\n\n“同盟。”陆淮舟纠正，“第四页约定第二条生效前提，是你拿到证据闭环。现在闭环完成，我兑现承诺。”他掏出手机解锁，屏幕转向林满月。文件管理器界面，蓝光映在他眼底。\n\n“"
