   "num": 22,
   "title": "阴影里的银色表带",
   "words": 2623,
   "content": "黑色轿车无声地滑入侧门阴影，引擎熄火后的余温在夜风中迅速冷却。林满月踩上粗糙的水泥地，视网膜左上角的红光剧烈跳动，像某种濒死的心脏——那是系统倒计时，并非医疗仪器：【倒计时 10 小时 45 分】。时间流速不对劲。\n\n“陆老师走 VIP 通道。”安保队长指着旋转门内侧的隐蔽入口，“林编剧，走员工安检口。直播期间，核验升级。”\n\n陆淮舟没立刻下车，微微探出头，帽檐下目光扫过队长，落在林满月脸上。“进去后别乱跑。”声音不高，透着命令。\n\n“放心。”林满月拉了拉帆布袋带子，指尖发凉，“我要是真乱跑，节目停播你赔？”\n\n车门关上，引擎声远去。安保队长盯着背影，直到安检门绿灯亮起才松气。陆淮舟绕到车后座，推门下车，黑色连帽衫的帽子压得很低，帽檐死死压在后颈，遮住了半张脸。安保队长识趣地引路，穿过侧门隐蔽的 VIP 电梯井。电梯直上顶层，数字跳动间，陆淮舟按亮手机屏幕，确认信号稳定。走出电梯，总控室的感应门自动滑开，冷气扑面而来。\n\n总控室位于顶层。玻璃墙外是演播大厅俯瞰视角，无数灯光如星河倒悬。\n\n陆淮舟站在主屏幕前。小鹿摊开三台笔记本，代码流如瀑布般冲刷着屏幕。“端口波动率超阈值，”她敲着键盘，手指因紧张而泛白，“第 7 个关键点……激活了。”\n\n“谁写的干扰代码？”“看不全。”技术骨干脸色发白，额头上渗出细密的汗珠，“有加密层。底层逻辑像是……实时抓取观众情绪值。”\n\n陆淮舟点开日志，红字闪烁：【信号源异常，建议切断连接】。“切断。”“不行！”技术骨干抬头，声音颤抖，“切断直播会黑屏，资方会炸锅。代码嵌在核心里，切不掉。”\n\n陆淮舟关掉屏幕。王丽和总监只是棋子，真正动手的人权限更高。他看向时间，拨通林满月频道。“到哪了？”“地下二层。”“放弃。”“证据链需物理确认。”林满月声音带杂音，“若是上传装置，必须拔掉。”“陷阱。”“知道。”电话挂断。陆淮舟盯着监控电梯，手心出汗。系统封锁"
