   "num": 23,
   "title": "打印纸上的高危评估",
   "words": 2600,
   "content": "金属格栅被从内部推开，发出刺耳的摩擦声。地下二层的风井出口位于维修通道尽头，应急红灯在头顶频闪，把两人的影子拉得忽长忽短。空气里弥漫着焦糊味，像是电路板过载后烧焦的绝缘皮。\n\n陆助理扶着林满月往下挪了一级台阶，压低声音：“安保队已经封锁了 B 区入口，走检修梯。”\n\n“他们追上来之前能到车吗？”林满月没问废话，只盯着视网膜左上角的红色数字。【09 小时 41 分 59 秒】依然定格不动。\n\n“陆老师刚切断总控室连接，车就在下面等着，路线是私道，监控盲区。”陆助理指了指侧面的铁门，“他一直在监控位直到最后一刻，快。”\n\n两人顺着锈迹斑斑的梯子爬出通风管道，落地时避开了一排正在巡逻的红外感应器。陆助理熟门熟路地带着她穿过杂物堆，十分钟后，黑色防弹车的引擎声在阴影中响起。\n\n车门落锁的瞬间，车厢内的气压仿佛都变了。隔音玻璃彻底隔绝了外界噪音，只留下车载电脑主机低沉的运行声。林满月靠在真皮座椅上，掌心还在发烫。刚才拔下终端硬盘盒时留下的伤口不见了，取而代之的是皮肤下隐约浮现的淡蓝色微光纹路，像某种生物电路，随着她的脉搏搏动两下，随后隐入皮下。好在拔下终端硬盘盒的瞬间，她利用端口权限强行切断了信号流，自毁程序虽因触碰边缘已被触发，却未能执行。“系统过载反应。”陆淮舟坐在驾驶位，视线没有离开前方路况，语气平淡得像在谈论天气，“非物理伤害，是标记同化。你碰了核心逻辑层，它把你识别为‘兼容端口’。”\n\n林满月把手举到灯光下，指缝间没有血迹，只有那转瞬即逝的蓝光。“所以我的‘弹幕视觉’也是植入的？”\n\n“是实验产物。”陆淮舟单手插兜，另一只手操控方向盘绕过一处减速带，“《心动倒计时》不是综艺，是情绪操控服从度测试。总监只是第七个失败执行者。”\n\n“执行什么？”\n\n“筛选高敏感度个体，接入情感数据流，转化为指令。”陆淮舟终于转头看她一眼，眼底藏着极深的疲惫，“前六个执行者要么疯了，要么消失了。"
