   "[第17章] 碎片上的签名是综艺部总监的字迹，林满月在季度全员会议的台历上见过该签名样式",
   "[第17章] 新IP在19:25访问导播台端口，IP前缀'192.168.1.xxx'与总监办公室固定路由器前缀匹配",
   "[第17章] 该IP是第一次触发隐藏访问节点，操作痕迹与之前的加密节点完全匹配，账号被系统标记为'未知设备'，只有总监办公室的公用电脑能分配到这个IP",
   "[第17章] 陆淮舟提供监控备份，显示他的电脑在最新黑料发布前10分钟远程访问了导播台端口，但加密账号的权限被锁，查不了具体操作",
   "[第17章] 陆淮舟提出条件：48小时内找到端口操作者，他就把伪造签名的完整证据给林满月，倒计时剩余22小时左右",
   "[第17章] 林满月收到陌生号码威胁短信，文字为'停止调查，后果自负'，附公寓楼大门照片，角度从对面梧桐树枝后拍，细节清晰",
   "[第17章] 倒计时剩余21小时41分，林满月意识到对方在监视她并已摸到她的生活里",
   "[第17章] 碎片编号F070的F是风井的首字母，而070恰好是总监办公室在组织架构图上的房间编号",
   "[第17章] 陆淮舟手绘图背面写'那天有人比你先到'，字迹是陆淮舟的",
   "[第17章] 林满月发现照片里多了一个身影，站在梧桐树后，穿着藏青色外套，袖口露出一截银色表带",
   "[第17章] 林满月确认该身影的轮廓和快印店监控截帧里的人完全重合——外聘剪辑",
   "[第17章] 林满月意识到从资料室拼图开始，到技术部查IP，再到收到威胁短信，每一个环节都不是偶然",
   "[第17章] 林满月发现陆淮舟手绘图背面写'那天有人比你先到'——那个人，是不是你？",
   "[第17章·关系] {\"a\": \"林满月\", \"b\": \"陆淮舟\", \"type\": \"合作交涉\", \"change\": \"林满月提出合作条件（陆淮舟提供技术部监控备份，她查签名和编号），陆淮舟同意但附加条件（只报合规链路，不扩散内部端口细节）\"}",
   "[第17章·关系] {\"a\": \"林满月\", \"b\": \"小鹿\", \"type\": \"上下级协作\", \"change\": \"林满月发消息要求小鹿带端口日志来技术部，小鹿提供新IP记录并执行查IP任务\"}",
   "[第17章·关系] {\"a\": \"林满月\", \"b\": \"王丽\", \"type\": \"上下级冲突\", \"change\": \"林满月发现碎片上的总监签名，想起王丽承认伪造签名和布局，关系恶化\"}",
   "[第17章·关系] {\"a\": \"林满月\", \"b\": \"陆助理\", \"type\": \"信息传递/协作\", \"change\": \"林满月收到陌生号码要挟短信后立即截图转发给陆助理；陆助理送达U盘并转达陆淮舟条件\"}",
   "[第17章·关系] {\"a\": \"陌生号码\", \"b\": \"林满月\", \"type\": \"威胁/约见\", \"change\": \"短信称地库照片原始文件在其手中，要求林满月独自前往取回；林满月回复'定'\"}",
   "[第17章·关系] {\"a\": \"外聘剪辑\", \"b\": \"林满月\", \"type\": \"证据移交/信息交换\", \"change\": \"外聘剪辑主动联系并提供SD卡原片与打印回执，林满月录音固定证词\"}",
   "[第17章·关系] {\"a\": \"外聘剪辑\", \"b\": \"周明\", \"type\": \"被利用/被警告\", \"change\": \"周明借卡给外聘剪辑拍空镜、让其代跑快印店制版、事后警告其闭嘴；外聘剪辑自述被当枪使\"}",
   "[第17章·关系] {\"a\": \"林满月\", \"b\": \"小鹿\", \"type\": \"应急安排/同盟\", \"change\": \"林满月设置暗号'我把帧拉满了'，若发出则小鹿转U盘给陆助理、人别来\"}",
   "[第17章·情感] {\"character\": \"林满月\", \"turn\": \"从冷静拼图到发现总监签名时的震惊，再到与陆淮舟交涉时的平稳，最后收到威胁短信时指尖凉意钻心脏的寒意与警惕\"}",
   "[第17章·情感] {\"character\": \"林满月\", \"turn\": \"看到照片中多出的身影后手指僵住，放大照片确认是外聘剪辑，想起其说过的话，意识到事情没那么简单\"}",
   "[第17章·情感] {\"character\": \"林满月\", \"turn\": \"发现碎片编号F070中F是风井、070是总监办公室房间号后，感到指尖凉意顺着动脉蔓延至心口，意识到有人在陪她走这段路\"}",
   "[第17章·情感] {\"character\": \"陆淮舟\", \"turn\": \"低沉克制，提供信息时语气无起伏，同意合作但强调合规\"}",
