   "time_advance": "本章时间从下午资料室拼碎片开始，经消防通道会面、技术部查IP，至工位收到威胁短信结束，倒计时从23小时41分推进到21小时41分，约2小时",
   "facts": [
    "碎片上的编号'F070'与陆淮舟手绘风井位置俯视图上的检修梯第三级编号尾数完全吻合",
    "碎片上的签名是综艺部总监的字迹，林满月在季度全员会议的台历上见过该签名样式",
    "新IP在19:25访问导播台端口，IP前缀'192.168.1.xxx'与总监办公室固定路由器前缀匹配",
    "该IP是第一次触发隐藏访问节点，操作痕迹与之前的加密节点完全匹配，账号被系统标记为'未知设备'，只有总监办公室的公用电脑能分配到这个IP",
    "陆淮舟提供监控备份，显示他的电脑在最新黑料发布前10分钟远程访问了导播台端口，但加密账号的权限被锁，查不了具体操作",
    "陆淮舟提出条件：48小时内找到端口操作者，他就把伪造签名的完整证据给林满月，倒计时剩余22小时左右",
    "林满月收到陌生号码威胁短信，文字为'停止调查，后果自负'，附公寓楼大门照片，角度从对面梧桐树枝后拍，细节清晰",
    "倒计时剩余21小时41分，林满月意识到对方在监视她并已摸到她的生活里",
    "碎片编号F070的F是风井的首字母，而070恰好是总监办公室在组织架构图上的房间编号",
    "陆淮舟手绘图背面写'那天有人比你先到'，字迹是陆淮舟的",
    "林满月发现照片里多了一个身影，站在梧桐树后，穿着藏青色外套，袖口露出一截银色表带",
    "林满月确认该身影的轮廓和快印店监控截帧里的人完全重合——外聘剪辑",
    "林满月意识到从资料室拼图开始，到技术部查IP，再到收到威胁短信，每一个环节都不是偶然"
   ],
